(* Independent pre-search literal terms; live reconstructed objects required. *)
let crypto_observation_json s="\"" ^ String.escaped s ^ "\"";;
let crypto_observation_audit initial_axioms path =
 let claims=[
  ("ASSURANCE_DECODED_OBSERVATION_ALL_SUCCESSORS",parse_term "!len inst s s'.\n    x86_decode s (read RIP s) (len,inst) /\\ x86 s s'\n    ==> assurance_observed_step s\n          (assurance_observation s len inst s') s'",ASSURANCE_DECODED_OBSERVATION_ALL_SUCCESSORS);
  ("CRYPTO_OBSERVATION_BODY7",parse_term "!pc p q count m (s:x86state).\n    0<count /\\ count<2 EXP 64 /\\\n    bytes_loaded s (word pc) crypto_memcmp_mc /\\\n    read RIP s=word(pc+64) /\\ read RDI s=p /\\ read RSI s=q /\\\n    read RDX s=word count /\\ read memory s=m\n    ==> crypto_observed_run (crypto_public_body7 pc p q count)\n      (\\s'. read RIP s'=(if count=1 then word(pc+86) else word(pc+64)) /\\\n            read RDI s'=word_add p (word 1) /\\\n            read RSI s'=word_add q (word 1) /\\\n            read RDX s'=word(count-1) /\\ read memory s'=m /\\\n            bytes_loaded s' (word pc) crypto_memcmp_mc) s",CRYPTO_OBSERVATION_BODY7);
  ("CRYPTO_OBSERVATION_LOOP",parse_term "!n pc stackpointer returnaddress p q m (s:x86state).\n    0<n /\\ n<2 EXP 64 /\\\n    bytes_loaded s (word pc) crypto_memcmp_mc /\\\n    read RIP s=word(pc+64) /\\ read RSP s=stackpointer /\\\n    read (memory :> bytes64 stackpointer) s=returnaddress /\\\n    read RDI s=p /\\ read RSI s=q /\\ read RDX s=word n /\\ read memory s=m\n    ==> crypto_observed_run (crypto_public_loop pc p q n stackpointer returnaddress)\n      (\\s'. read RIP s'=returnaddress /\\\n            read RSP s'=word_add stackpointer (word 8) /\\\n            read memory s'=m /\\ bytes_loaded s' (word pc) crypto_memcmp_mc) s",CRYPTO_OBSERVATION_LOOP);
  ("CRYPTO_OBSERVATION_CALLABLE",parse_term "!pc stackpointer returnaddress p q n m (s:x86state).\n    n<2 EXP 64 /\\ bytes_loaded s (word pc) crypto_memcmp_mc /\\\n    read RIP s=word pc /\\ read RSP s=stackpointer /\\\n    read (memory :> bytes64 stackpointer) s=returnaddress /\\\n    C_ARGUMENTS [p;q;word n] s /\\ read memory s=m\n    ==> crypto_observed_run (crypto_public_call pc p q n stackpointer returnaddress)\n      (\\s'. read RIP s'=returnaddress /\\\n            read RSP s'=word_add stackpointer (word 8) /\\\n            read memory s'=m /\\ bytes_loaded s' (word pc) crypto_memcmp_mc) s",CRYPTO_OBSERVATION_CALLABLE);
  ("CRYPTO_OBSERVATION_UNIQUE",parse_term "!s obs1 obs2 (s':x86state).\n    assurance_observed_step s obs1 s' /\\ assurance_observed_step s obs2 s'\n    ==> obs1=obs2",CRYPTO_OBSERVATION_UNIQUE);
  ("CRYPTO_OBSERVATION_MONO",parse_term "!trace P Q (s:x86state).\n    (!t. P t ==> Q t) /\\ crypto_observed_run trace P s\n    ==> crypto_observed_run trace Q s",CRYPTO_OBSERVATION_MONO);
  ("CRYPTO_OBSERVATION_PROJECT",parse_term "!trace P (s:x86state).\n    crypto_observed_run trace P s ==> eventually_n x86 (LENGTH trace) P s",CRYPTO_OBSERVATION_PROJECT);
  ("CRYPTO_OBSERVATION_EXECUTION_EXACT",parse_term "!trace P (s:x86state) other t.\n    crypto_observed_run trace P s /\\ LENGTH other=LENGTH trace /\\\n    crypto_observed_execution other s t\n    ==> other=trace /\\ P t",CRYPTO_OBSERVATION_EXECUTION_EXACT);
  ("CRYPTO_OBSERVATION_LOOP_LENGTH",parse_term "!n pc (p:int64) q stackpointer returnaddress.\n    LENGTH(crypto_public_loop pc p q n stackpointer returnaddress)=7*n+3",CRYPTO_OBSERVATION_LOOP_LENGTH);
  ("CRYPTO_OBSERVATION_CALL_LENGTH",parse_term "!pc (p:int64) q n stackpointer returnaddress.\n    LENGTH(crypto_public_call pc p q n stackpointer returnaddress)=\n      (if n=0 then 6 else if n=16 then 15 else 7*n+10)",CRYPTO_OBSERVATION_CALL_LENGTH);
  ("CRYPTO_OBSERVATION_E2",parse_term "!pc stackpointer returnaddress p q n m rp xp ordinary (s:x86state).\n    bp_e2_crypto_pre pc stackpointer returnaddress p q n m rp xp ordinary s\n    ==> crypto_observed_run (crypto_public_call pc p q n stackpointer returnaddress)\n          (\\s'. read RIP s'=returnaddress /\\\n                read RSP s'=word_add stackpointer (word 8)) s",CRYPTO_OBSERVATION_E2);
  ("CRYPTO_OBSERVATION_RELATIONAL",parse_term "!pc stackpointer returnaddress p q n m1 m2 rp xp ordinary (s1:x86state) s2.\n    bp_e2_crypto_pre pc stackpointer returnaddress p q n m1 rp xp ordinary s1 /\\\n    bp_e2_crypto_pre pc stackpointer returnaddress p q n m2 rp xp ordinary s2\n    ==> crypto_observed_run (crypto_public_call pc p q n stackpointer returnaddress)\n          (\\s'. read RIP s'=returnaddress /\\\n                read RSP s'=word_add stackpointer (word 8)) s1 /\\\n        crypto_observed_run (crypto_public_call pc p q n stackpointer returnaddress)\n          (\\s'. read RIP s'=returnaddress /\\\n                read RSP s'=word_add stackpointer (word 8)) s2",CRYPTO_OBSERVATION_RELATIONAL);
  ("CRYPTO_OBSERVATION_ALL_PAIRS",parse_term "!pc stackpointer returnaddress p q n m1 m2 rp xp ordinary\n       (s1:x86state) s2 trace1 trace2 t1 t2.\n    bp_e2_crypto_pre pc stackpointer returnaddress p q n m1 rp xp ordinary s1 /\\\n    bp_e2_crypto_pre pc stackpointer returnaddress p q n m2 rp xp ordinary s2 /\\\n    LENGTH trace1=(if n=0 then 6 else if n=16 then 15 else 7*n+10) /\\\n    LENGTH trace2=(if n=0 then 6 else if n=16 then 15 else 7*n+10) /\\\n    crypto_observed_execution trace1 s1 t1 /\\\n    crypto_observed_execution trace2 s2 t2\n    ==> trace1=crypto_public_call pc p q n stackpointer returnaddress /\\\n        trace2=crypto_public_call pc p q n stackpointer returnaddress /\\\n        trace1=trace2",CRYPTO_OBSERVATION_ALL_PAIRS);
  ("CRYPTO_FIRST_RET_SHAPE_CHARACTERIZATION",parse_term "!trace:(int64#num#instruction#uarch_event list)list.\n    crypto_ret_shape trace <=>\n    ~(trace=[]) /\\ crypto_observation_is_ret (LAST trace) /\\\n    ALL (\\obs. ~crypto_observation_is_ret obs) (BUTLAST trace)",CRYPTO_FIRST_RET_SHAPE_CHARACTERIZATION);
  ("CRYPTO_FIRST_RET_EXECUTION_EQUIVALENT",parse_term "!trace (s:x86state) t.\n    crypto_first_ret_execution trace s t <=>\n    crypto_observed_execution trace s t /\\ crypto_ret_shape trace",CRYPTO_FIRST_RET_EXECUTION_EQUIVALENT);
  ("CRYPTO_FIRST_RET_PREFIX",parse_term "!prefix suffix:(int64#num#instruction#uarch_event list)list.\n    ALL (\\obs. ~crypto_observation_is_ret obs) prefix /\\ crypto_ret_shape suffix\n    ==> crypto_ret_shape (APPEND prefix suffix)",CRYPTO_FIRST_RET_PREFIX);
  ("CRYPTO_FIRST_RET_FORCE",parse_term "!public P (s:x86state) other t.\n    crypto_observed_run public P s /\\ crypto_ret_shape public /\\\n    crypto_first_ret_execution other s t\n    ==> other=public /\\ P t",CRYPTO_FIRST_RET_FORCE);
  ("CRYPTO_FIRST_RET_LOOP_SHAPE",parse_term "!n pc (p:int64) q stackpointer returnaddress.\n    crypto_ret_shape (crypto_public_loop pc p q n stackpointer returnaddress)",CRYPTO_FIRST_RET_LOOP_SHAPE);
  ("CRYPTO_FIRST_RET_CALL_SHAPE",parse_term "!pc (p:int64) q n stackpointer returnaddress.\n    crypto_ret_shape (crypto_public_call pc p q n stackpointer returnaddress)",CRYPTO_FIRST_RET_CALL_SHAPE);
  ("CRYPTO_FIRST_RET_RELATIONAL",parse_term "!pc stackpointer returnaddress p q n m1 m2 rp xp ordinary\n       (s1:x86state) s2 trace1 trace2 t1 t2.\n    bp_e2_crypto_pre pc stackpointer returnaddress p q n m1 rp xp ordinary s1 /\\\n    bp_e2_crypto_pre pc stackpointer returnaddress p q n m2 rp xp ordinary s2 /\\\n    crypto_first_ret_execution trace1 s1 t1 /\\\n    crypto_first_ret_execution trace2 s2 t2\n    ==> trace1=crypto_public_call pc p q n stackpointer returnaddress /\\\n        trace2=crypto_public_call pc p q n stackpointer returnaddress /\\\n        trace1=trace2 /\\\n        read RIP t1=returnaddress /\\ read RSP t1=word_add stackpointer (word 8) /\\\n        read RIP t2=returnaddress /\\ read RSP t2=word_add stackpointer (word 8)",CRYPTO_FIRST_RET_RELATIONAL);
  ("CRYPTO_OBSERVATION_EXECUTION_EXISTS",parse_term "!trace P s. crypto_observed_run trace P s ==>\n    ?t. crypto_observed_execution trace s t /\\ P t",CRYPTO_OBSERVATION_EXECUTION_EXISTS);
  ("CRYPTO_FIRST_RET_EXECUTION_EXISTS",parse_term "!trace P s. crypto_observed_run trace P s /\\ crypto_ret_shape trace ==>\n    ?t. crypto_first_ret_execution trace s t /\\ P t",CRYPTO_FIRST_RET_EXECUTION_EXISTS);
  ("CRYPTO_FIRST_RET_E2_EXISTS",parse_term "!pc stackpointer returnaddress p q n m rp xp ordinary s.\n   bp_e2_crypto_pre pc stackpointer returnaddress p q n m rp xp ordinary s ==>\n   ?t. crypto_first_ret_execution\n        (crypto_public_call pc p q n stackpointer returnaddress) s t /\\\n       read RIP t=returnaddress /\\ read RSP t=word_add stackpointer (word 8)",CRYPTO_FIRST_RET_E2_EXISTS)] in
 let definitions=[
  ("crypto_observed_run",parse_term "(crypto_observed_run [] (P:x86state->bool) s <=> P s) /\\\n  (crypto_observed_run (CONS (obs:int64#num#instruction#uarch_event list) rest) P s <=>\n     (?s'. x86 s s') /\\\n     !s'. x86 s s' ==> assurance_observed_step s obs s' /\\\n                         crypto_observed_run rest P s')",crypto_observed_run);
  ("crypto_observed_execution",parse_term "(crypto_observed_execution [] (s:x86state) t <=> t=s) /\\\n  (crypto_observed_execution (CONS (obs:int64#num#instruction#uarch_event list) rest) s t <=>\n     ?next. assurance_observed_step s obs next /\\\n            crypto_observed_execution rest next t)",crypto_observed_execution);
  ("crypto_public_decode",parse_term "crypto_public_decode off =\n    if off=0 then (4,ENDBR64)\n    else if off=4 then (3,XOR (% rax) (% rax))\n    else if off=7 then (3,XOR (% r10) (% r10))\n    else if off=10 then (4,CMP (% rdx) (Imm8 (word 0)))\n    else if off=14 then (2,JUMP Condition_Z (Imm8 (word 77)))\n    else if off=16 then (4,CMP (% rdx) (Imm8 (word 16)))\n    else if off=20 then (2,JUMP Condition_NZ (Imm8 (word 42)))\n    else if off=22 then (3,MOV (% r10) (Memop Quadword (%% (rdi,0))))\n    else if off=25 then (4,MOV (% r11) (Memop Quadword (%% (rdi,8))))\n    else if off=29 then (7,MOV (% rdx) (Imm32 (word 1)))\n    else if off=36 then (3,XOR (% r10) (Memop Quadword (%% (rsi,0))))\n    else if off=39 then (4,XOR (% r11) (Memop Quadword (%% (rsi,8))))\n    else if off=43 then (3,OR (% r10) (% r11))\n    else if off=46 then (4,CMOV Condition_NZ (% rax) (% rdx))\n    else if off=50 then (2,RET)\n    else if off=64 then (3,MOV (% r10b) (Memop Byte (%% (rdi,0))))\n    else if off=67 then (4,LEA (% rdi) (%% (rdi,1)))\n    else if off=71 then (3,XOR (% r10b) (Memop Byte (%% (rsi,0))))\n    else if off=74 then (4,LEA (% rsi) (%% (rsi,1)))\n    else if off=78 then (3,OR (% al) (% r10b))\n    else if off=81 then (3,DEC (% rdx))\n    else if off=84 then (2,JUMP Condition_NZ (Imm8 (word 234)))\n    else if off=86 then (3,NEG (% rax))\n    else if off=89 then (4,SHR (% rax) (Imm8 (word 63)))\n    else if off=93 then (2,RET)\n    else (0,RET)",crypto_public_decode);
  ("crypto_public_observation",parse_term "crypto_public_observation pc off (es:uarch_event list) =\n    (word(pc+off):int64,FST(crypto_public_decode off),SND(crypto_public_decode off),es)",crypto_public_observation);
  ("crypto_public_entry5",parse_term "crypto_public_entry5 pc n =\n   [crypto_public_observation pc 0 [];\n    crypto_public_observation pc 4 [];\n    crypto_public_observation pc 7 [];\n    crypto_public_observation pc 10 [];\n    crypto_public_observation pc 14\n      [EventJump(word(pc+16),if n=0 then word(pc+93) else word(pc+16))]]",crypto_public_entry5);
  ("crypto_public_entry7",parse_term "crypto_public_entry7 pc n = APPEND (crypto_public_entry5 pc n)\n   [crypto_public_observation pc 16 [];\n    crypto_public_observation pc 20\n      [EventJump(word(pc+22),if n=16 then word(pc+22) else word(pc+64))]]",crypto_public_entry7);
  ("crypto_public_body7",parse_term "crypto_public_body7 pc (p:int64) q count =\n   [crypto_public_observation pc 64 [EventLoad(p,1)];\n    crypto_public_observation pc 67 [];\n    crypto_public_observation pc 71 [EventLoad(q,1)];\n    crypto_public_observation pc 74 [];\n    crypto_public_observation pc 78 [];\n    crypto_public_observation pc 81 [];\n    crypto_public_observation pc 84\n      [EventJump(word(pc+86),if count=1 then word(pc+86) else word(pc+64))]]",crypto_public_body7);
  ("crypto_public_exit",parse_term "crypto_public_exit pc (stackpointer:int64) returnaddress =\n   [crypto_public_observation pc 86 [];\n    crypto_public_observation pc 89 [];\n    crypto_public_observation pc 93\n      [EventLoad(stackpointer,8);EventJump(word(pc+95),returnaddress)]]",crypto_public_exit);
  ("crypto_public_loop",parse_term "(crypto_public_loop pc (p:int64) q 0 stackpointer returnaddress =\n     crypto_public_exit pc stackpointer returnaddress) /\\\n  (crypto_public_loop pc p q (SUC n) stackpointer returnaddress =\n     APPEND (crypto_public_body7 pc p q (SUC n))\n       (crypto_public_loop pc (word_add p (word 1)) (word_add q (word 1)) n\n         stackpointer returnaddress))",crypto_public_loop);
  ("crypto_public_call",parse_term "crypto_public_call pc (p:int64) q n stackpointer returnaddress =\n   if n=0 then APPEND (crypto_public_entry5 pc 0)\n    [crypto_public_observation pc 93\n      [EventLoad(stackpointer,8);EventJump(word(pc+95),returnaddress)]]\n   else if n=16 then APPEND (crypto_public_entry7 pc 16)\n    [crypto_public_observation pc 22 [EventLoad(p,8)];\n     crypto_public_observation pc 25 [EventLoad(word_add p (word 8),8)];\n     crypto_public_observation pc 29 [];\n     crypto_public_observation pc 36 [EventLoad(q,8)];\n     crypto_public_observation pc 39 [EventLoad(word_add q (word 8),8)];\n     crypto_public_observation pc 43 [];\n     crypto_public_observation pc 46 [];\n     crypto_public_observation pc 50\n      [EventLoad(stackpointer,8);EventJump(word(pc+52),returnaddress)]]\n   else APPEND (crypto_public_entry7 pc n)\n     (crypto_public_loop pc p q n stackpointer returnaddress)",crypto_public_call);
  ("crypto_observation_is_ret",parse_term "crypto_observation_is_ret (obs:int64#num#instruction#uarch_event list) <=>\n    FST(SND(SND obs)) = RET",crypto_observation_is_ret);
  ("crypto_first_ret_execution",parse_term "crypto_first_ret_execution trace (s:x86state) t <=>\n    ~(trace=[]) /\\ crypto_observed_execution trace s t /\\\n    crypto_observation_is_ret (LAST trace) /\\\n    ALL (\\obs. ~crypto_observation_is_ret obs) (BUTLAST trace)",crypto_first_ret_execution);
  ("crypto_ret_shape",parse_term "(crypto_ret_shape [] <=> F) /\\\n  (crypto_ret_shape (CONS (obs:int64#num#instruction#uarch_event list) rest) <=>\n     if crypto_observation_is_ret obs then rest=[] else crypto_ret_shape rest)",crypto_ret_shape);
 ] in
 let records=List.map(fun(name,expected,th)->
  if hyp th<>[] then failwith(name^": hypotheses");
  if not(aconv(concl th) expected) then failwith(name^": wrong exact conclusion");
  if axioms()<>initial_axioms then failwith(name^": new axioms");
  "{\"name\":"^crypto_observation_json name^
  ",\"hypothesis_count\":0,\"conclusion_matches_expected\":true,\"new_axioms\":0,"^
  "\"statement\":"^crypto_observation_json(string_of_term(concl th))^"}") claims in
 let defs=List.map(fun(name,expected,th)->
  if hyp th<>[] then failwith(name^": definition hypotheses");
  if not(aconv(snd(strip_forall(concl th))) expected) then failwith(name^": expanded definition mismatch");
  "{\"name\":"^crypto_observation_json name^",\"equation_matches_expected\":true,\"hypothesis_count\":0,\"statement\":"^
  crypto_observation_json(string_of_term(concl th))^"}") definitions in
 let oc=open_out path in output_string oc
  ("{\"status\":\"PASS_ALL_LENGTH_ARCHITECTURAL_OBSERVATION_COMPONENT\",\"full_O2_pass\":false,"^
  "\"scope\":\"Exact whole original transition observation schema; progress+every successor; actual preRIP/decoded length/instruction/ordered event deltas; same-E2-Pre arbitrary memories, actual execution existence and every actual first-RET execution pair without a length or result-equality premise; physical/microarchitectural correspondence separate\","^
  "\"theorems\":["^String.concat "," records^"],\"expanded_definitions\":["^String.concat "," defs^"]}\n");close_out oc;;
